% Andrii Kholod EDIfu25/2 20255272
x = 0:0.1:2*pi;

f1 = x.^3 + tan(x);
f2 = exp(x);
f3 = exp(3*x);
f4 = exp(5*x);

figure(1); %[output:45c49814]
plot(x, f1, '-k'); %[output:45c49814]
xlabel('x values'); %[output:45c49814]
ylabel('f_1(x)'); %[output:45c49814]
title('Graph of f_1(x) = x^3 + tan(x)'); %[output:45c49814]
grid on; %[output:45c49814]
axis([0, 2*pi, -100, 300]);  %[output:45c49814]

figure(2); %[output:75d83823]
semilogy(x, f2, '-or', x, f3, '--xg', x, f4, '-.*b'); %[output:75d83823]
xlabel('x values'); %[output:75d83823]
ylabel('Exponential Function Outputs (Log Scale)'); %[output:75d83823]
title('Comparison of Exponential Functions'); %[output:75d83823]
grid on; %[output:75d83823]
axis([0, 2*pi, 1, exp(10*pi)]);  %[output:75d83823]
legend('f_2(x) = e^x', 'f_3(x) = e^{3x}', 'f_4(x) = e^{5x}', 'Location', 'northwest'); %[output:75d83823]

marks = randi([1, 10], 6, 4);
figure; %[output:5755c3d9]
subplot(2, 1, 1); %[output:5755c3d9]
bar(marks); %[output:5755c3d9]
title('Individual Exam Results per Student'); %[output:5755c3d9]
xlabel('Student Number'); %[output:5755c3d9]
ylabel('Exam Mark'); %[output:5755c3d9]
xlim([0, 7]); %[output:5755c3d9]
ylim([0, 12]); %[output:5755c3d9]
legend('Exam 1', 'Exam 2', 'Exam 3', 'Exam 4'); %[output:5755c3d9]
subplot(2, 1, 2); %[output:5755c3d9]
bar(marks, 'stacked'); %[output:5755c3d9]
title('Total Exam Results per Student'); %[output:5755c3d9]
xlabel('Student Number'); %[output:5755c3d9]
ylabel('Total Sum of Marks'); %[output:5755c3d9]
xlim([0, 7]); %[output:5755c3d9]
ylim([0, 45]); %[output:5755c3d9]

